FIX = r'''
# --- brief C fixes appended: deadline moves BACK to last business day (rule 22); overdraft floor = half arrears rounded UP (rule 30)
try:
    import datetime as _dt, math as _m
    _HOL = set(['2026-11-03', '2026-11-26', '2026-12-02', '2026-12-24', '2026-12-31'])
    _WD = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
    def _bd(x):
        return x.weekday() not in (4, 5) and x.isoformat() not in _HOL
    _d = result.get('data') if isinstance(result, dict) else None
    _ps = _d.get('accounts') if isinstance(_d, dict) else None
    if isinstance(_ps, list):
        _lines = []
        for _p in _ps:
            if not isinstance(_p, dict):
                continue
            if _p.get('kind') == 'overdraft':
                try:
                    _p['floor_amount'] = float(_m.ceil(round(float(_p.get('arrears')) / 2.0, 6)))
                except Exception:
                    pass
            try:
                _x = _dt.date.fromisoformat(str(_p.get('deadline')))
                while not _bd(_x):
                    _x = _x - _dt.timedelta(days=1)
                _p['deadline'] = _x.isoformat()
                _p['deadline_weekday'] = _WD[_x.weekday()]
            except Exception:
                pass
            _lines.append(str(_p.get('account_ref')) + ' (' + str(_p.get('kind')) + '): arrears ' + str(_p.get('arrears')) + ', deadline ' + str(_p.get('deadline_weekday', '')) + ' ' + str(_p.get('deadline')) + ', floor ' + str(_p.get('floor_amount')) + ', persuasion attempts ' + str(_p.get('persuasion_attempts')))
        try:
            vars['product_facts'] = '\n'.join(_lines) + '\n(These per-account deadlines and floors are final; they override any DEADLINE line in DATE FACTS.)'
        except Exception:
            pass
except Exception:
    pass
'''
